fn ordinal(n:usize)->Result<Cell<'static>, ValueError>{Ok(Cell::Integer(i64::try_from(n).map_err(|e| invalid(e.to_string()))?))}
fn checkpoint(c:&mut SqliteSnapshotControl<'_>,n:usize,total:usize)->Result<(), ValueError>{if n%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,total)?;}Ok(())}
type Entities<'a>=BTreeMap<i64,FloatRow<'a>>;
fn entities<'a>(d:&'a SqliteDatabase,table:&str,count:usize,floats:&'static[FloatColumn],c:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>, ValueError>{let rows=&d.table(table)?.rows;let mut out=Entities::new();for(n,row)in rows.iter().enumerate(){checkpoint(c,n,rows.len())?;let r=FloatRow::new(row,floats)?;if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=count||out.insert(r.rowid,r).is_some(){return Err(invalid("EN1993 identity or column shape differs"));}}Ok(out)}
fn ordered<'a>(rows:impl IntoIterator<Item=FloatRow<'a>>,parent:i64,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>, ValueError>{let mut out=BTreeMap::new();for(n,r)in rows.into_iter().enumerate(){checkpoint(c,n,0)?;let i=usize::try_from(r.integer(2)?).map_err(|e| invalid(e.to_string()))?;if r.integer(1)?!=parent||out.insert(i,r).is_some(){return Err(invalid("EN1993 parent or ordinal differs"));}}for(n,i)in out.keys().copied().enumerate(){checkpoint(c,n,out.len())?;if n!=i{return Err(invalid("EN1993 ordinals must be dense"));}}Ok(out.into_values().collect())}
fn groups<'a>(rows:Entities<'a>,parents:&Entities<'_>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<FloatRow<'a>>>, ValueError>{let mut out=BTreeMap::<i64,Vec<FloatRow<'a>>>::new();for(n,r)in rows.into_values().enumerate(){checkpoint(c,n,0)?;let p=r.integer(1)?;if !parents.contains_key(&p){return Err(invalid("EN1993 owning foreign key is dangling"));}out.entry(p).or_default().push(r);}Ok(out)}
fn text(r:FloatRow<'_>,i:usize,c:&mut SqliteSnapshotControl<'_>)->Result<String, ValueError>{reconstruct_text(c,r.text(i)?)}
fn uint(r:FloatRow<'_>,i:usize)->Result<u32, ValueError>{u32::try_from(r.integer(i)?).map_err(|e| invalid(e.to_string()))}
fn category(r:FloatRow<'_>,i:usize)->Result<u8, ValueError>{u8::try_from(r.integer(i)?).map_err(|e| invalid(e.to_string()))}
fn annex(a:AnnexChoice)->&'static str{match a{AnnexChoice::En=>"En",AnnexChoice::De=>"De"}}
fn read_annex(s:&str)->Result<AnnexChoice, ValueError>{match s{"En"=>Ok(AnnexChoice::En),"De"=>Ok(AnnexChoice::De),_=>Err(invalid("EN1993 annex differs"))}}
fn write_forces(p:&mut RowWriter<'_,'_>,table:&str,parent:i64,values:&[ForceAction])->Result<(), ValueError>{for(n,a)in values.iter().enumerate(){p.insert_float(table,&[Cell::Integer(parent),ordinal(n)?,Cell::Text(&a.id),Cell::Text(&a.load_case_id),Cell::Real(a.force)],FORCE)?;}Ok(())}
fn read_forces(rows:Vec<FloatRow<'_>>,parent:i64,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<ForceAction>, ValueError>{let mut out=Vec::new();for a in ordered(rows,parent,c)?{checkpoint(c,out.len(),0)?;out.push(ForceAction{id:text(a,3,c)?,load_case_id:text(a,4,c)?,force:a.real(5)?});}Ok(out)}
