  for(n,v)in self.members.iter().enumerate(){p.insert_float("en1993_member",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.label),Cell::Text(&v.member_type),Cell::Text(&v.section_id),Cell::Text(&v.material_id),Cell::Real(v.length),Cell::Real(v.buckling_length_y),Cell::Real(v.buckling_length_z),Cell::Real(v.ltb_length),Cell::Real(v.ltb_restraint_spacing),Cell::Text(&v.load_application),Cell::Real(v.end_moment_ratio_psi),Cell::Text(&v.moment_diagram),Cell::Real(v.deflection_limit_ratio),Cell::Text(&v.analysis)],MEMBER)?;}
  for(n,v)in self.load_cases.iter().enumerate(){p.insert("en1993_load_case",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.name),Cell::Text(&v.kind),Cell::Text(&v.category)])?;}
  for(n,v)in self.member_actions.iter().enumerate(){let a=&v.action;p.insert_float("en1993_member_action",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.member_id),Cell::Text(&v.load_case_id),Cell::Real(a.n),Cell::Real(a.vy),Cell::Real(a.vz),Cell::Real(a.my),Cell::Real(a.mz),Cell::Real(a.t)],DESIGN)?;}
  for(n,v)in self.joints.iter().enumerate(){let id=p.insert_float("en1993_joint",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.kind),Cell::Text(&v.member_id),Cell::Text(&v.bolt_class),Cell::Real(v.bolt_diameter),Cell::Integer(i64::from(v.bolt_rows)),Cell::Integer(i64::from(v.bolts_per_row)),Cell::Real(v.pitch),Cell::Real(v.gauge),Cell::Real(v.end_distance),Cell::Real(v.edge_distance),Cell::Integer(i64::from(v.shear_planes)),Cell::Real(v.plate_thickness),Cell::Real(v.plate_fu),Cell::Real(v.weld_throat),Cell::Real(v.weld_length),Cell::Real(v.weld_fu),Cell::Text(&v.weld_grade),Cell::Text(&v.category),Cell::Real(v.friction_mu),Cell::Real(v.preload_force),Cell::Real(v.slip_factor_ks),Cell::Integer(i64::from(v.friction_surfaces))],JOINT)?;for(k,a)in v.actions.iter().enumerate(){p.insert_float("en1993_joint_action",&[Cell::Integer(id),ordinal(k)?,Cell::Text(&a.id),Cell::Text(&a.load_case_id),Cell::Real(a.shear),Cell::Real(a.tension)],JOINT_ACTION)?;}}
  for(n,v)in self.fatigue_details.iter().enumerate(){let id=p.insert("en1993_fatigue_detail",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.member_id),Cell::Integer(i64::from(v.category)),Cell::Text(&v.method)])?;for(k,a)in v.spectrum.iter().enumerate(){p.insert_float("en1993_fatigue_band",&[Cell::Integer(id),ordinal(k)?,Cell::Text(&a.id),Cell::Real(a.delta_sigma),Cell::Real(a.cycles)],BAND)?;}}
  for(n,v)in self.fire_exposures.iter().enumerate(){p.insert_float("en1993_fire_exposure",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.member_id),Cell::Text(&v.rating),Cell::Real(v.protection_thickness),Cell::Real(v.section_factor),Cell::Real(v.mu0),Cell::Real(v.design_temperature),Cell::Real(v.protection_conductivity),Cell::Real(v.protection_density),Cell::Real(v.protection_specific_heat)],FIRE)?;}
  for(n,v)in self.cold_formed_members.iter().enumerate(){let id=p.insert_float("en1993_cold_formed_member",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Real(v.b_bar),Cell::Real(v.thickness),Cell::Real(v.k_sigma),Cell::Real(v.psi),Cell::Real(v.fy),Cell::Real(v.gross_resistance)],COLD)?;write_forces(p,"en1993_cold_formed_action",id,&v.actions)?;}
