  for(n,v)in self.piles.iter().enumerate(){let id=p.insert_float("en1993_pile",&[Cell::Integer(1),ordinal(n)?,Cell::Text(&v.id),Cell::Text(&v.section_id),Cell::Text(&v.material_id),Cell::Real(v.driving_stress),Cell::Real(v.embedded_length),Cell::Real(v.shaft_perimeter)],PILE)?;write_forces(p,"en1993_pile_action",id,&v.actions)?;}
