impl ArtifactSqliteSnapshot for En1993Snapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn decode_sqlite_snapshot_native(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{let limits=control.limits();store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record,native|{admission::admit(record,native,limits)?;Self::__dsl_from_record_controlled(record,native)},control)}

 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload, ValueError>{
  let mut rows=1usize;let mut visited=0usize;c.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;
  let mut add=|n:usize|->Result<(), ValueError>{rows=rows.checked_add(n).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1993 native row count overflow"))?;c.check_rows(rows)?;visited=visited.checked_add(1).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1993 native frontier count overflow"))?;if visited%256==0{c.checkpoint(SqliteSnapshotPhase::EncodeNative,rows,0)?;}Ok(())};
  for n in[self.materials.len(),self.sections.len(),self.members.len(),self.load_cases.len(),self.member_actions.len(),self.joints.len(),self.fatigue_details.len(),self.fire_exposures.len(),self.cold_formed_members.len(),self.plated_panels.len(),self.silo_shells.len(),self.tension_components.len(),self.bridge_fatigue.len(),self.tower_legs.len(),self.piles.len(),self.crane_runways.len()]{add(n)?;}
  for v in &self.joints{add(v.actions.len())?;}for v in &self.fatigue_details{add(v.spectrum.len())?;}for v in &self.cold_formed_members{add(v.actions.len())?;}for v in &self.plated_panels{add(v.actions.len())?;}for v in &self.tension_components{add(v.actions.len())?;}for v in &self.tower_legs{add(v.actions.len())?;}for v in &self.piles{add(v.actions.len())?;}for v in &self.crane_runways{add(v.actions.len())?;}
  c.checkpoint(SqliteSnapshotPhase::EncodeNative,0,rows)?;
  self.admit_sqlite_values(c,SqliteSnapshotPhase::EncodeNative)?;store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),c)
 }

 fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{
  let mut rows=RowWriter::new(Self::SQLITE_SCHEMA,c)?;self.write_sqlite_rows(&mut rows)?;rows.finish()
 }
 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self, ValueError>{
  c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits())?;let documents=entities(d,"en1993_document",2,&[],c)?;if documents.len()!=1||!documents.contains_key(&1){return Err(invalid("EN1993 requires one identity-1 document"));}let annex=read_annex(documents[&1].text(1)?)?;
  let joint_rows=entities(d,"en1993_joint",26,JOINT,c)?;let fatigue_rows=entities(d,"en1993_fatigue_detail",7,&[],c)?;let cold_rows=entities(d,"en1993_cold_formed_member",10,COLD,c)?;let plate_rows=entities(d,"en1993_plated_panel",9,PLATE,c)?;let tension_rows=entities(d,"en1993_tension_component",6,TENSION,c)?;let tower_rows=entities(d,"en1993_tower_leg",7,TOWER,c)?;let pile_rows=entities(d,"en1993_pile",9,PILE,c)?;let crane_rows=entities(d,"en1993_crane_runway",10,CRANE,c)?;
  let mut joint_actions=groups(entities(d,"en1993_joint_action",7,JOINT_ACTION,c)?,&joint_rows,c)?;let mut bands=groups(entities(d,"en1993_fatigue_band",6,BAND,c)?,&fatigue_rows,c)?;let mut cold_actions=groups(entities(d,"en1993_cold_formed_action",6,FORCE,c)?,&cold_rows,c)?;let mut plate_actions=groups(entities(d,"en1993_plated_action",6,FORCE,c)?,&plate_rows,c)?;let mut tension_actions=groups(entities(d,"en1993_tension_action",6,FORCE,c)?,&tension_rows,c)?;let mut tower_actions=groups(entities(d,"en1993_tower_action",6,FORCE,c)?,&tower_rows,c)?;let mut pile_actions=groups(entities(d,"en1993_pile_action",6,FORCE,c)?,&pile_rows,c)?;let mut crane_actions=groups(entities(d,"en1993_crane_action",6,FORCE,c)?,&crane_rows,c)?;
  let mut materials=Vec::new();for v in ordered(entities(d,"en1993_material",11,MATERIAL,c)?.into_values(),1,c)?{checkpoint(c,materials.len(),0)?;materials.push(SteelMaterial{id:text(v,3,c)?,grade:text(v,4,c)?,fy:v.real(5)?,fu:v.real(6)?,e_modulus:v.real(7)?,g_modulus:v.real(8)?,subgrade:text(v,9,c)?,kind:text(v,10,c)?});}
  let mut sections=Vec::new();for v in ordered(entities(d,"en1993_section",23,SECTION,c)?.into_values(),1,c)?{checkpoint(c,sections.len(),0)?;sections.push(SteelSection{id:text(v,3,c)?,designation:text(v,4,c)?,kind:text(v,5,c)?,h:v.real(6)?,b:v.real(7)?,tw:v.real(8)?,tf:v.real(9)?,r:v.real(10)?,area:v.real(11)?,shear_area_y:v.real(12)?,shear_area_z:v.real(13)?,iy:v.real(14)?,iz:v.real(15)?,it:v.real(16)?,iw:v.real(17)?,w_el_y:v.real(18)?,w_el_z:v.real(19)?,w_pl_y:v.real(20)?,w_pl_z:v.real(21)?,area_net:v.real(22)?});}
  let mut members=Vec::new();for v in ordered(entities(d,"en1993_member",18,MEMBER,c)?.into_values(),1,c)?{checkpoint(c,members.len(),0)?;members.push(SteelMember{id:text(v,3,c)?,label:text(v,4,c)?,member_type:text(v,5,c)?,section_id:text(v,6,c)?,material_id:text(v,7,c)?,length:v.real(8)?,buckling_length_y:v.real(9)?,buckling_length_z:v.real(10)?,ltb_length:v.real(11)?,ltb_restraint_spacing:v.real(12)?,load_application:text(v,13,c)?,end_moment_ratio_psi:v.real(14)?,moment_diagram:text(v,15,c)?,deflection_limit_ratio:v.real(16)?,analysis:text(v,17,c)?});}
  let mut load_cases=Vec::new();for v in ordered(entities(d,"en1993_load_case",7,&[],c)?.into_values(),1,c)?{checkpoint(c,load_cases.len(),0)?;load_cases.push(LoadCase{id:text(v,3,c)?,name:text(v,4,c)?,kind:text(v,5,c)?,category:text(v,6,c)?});}
  let mut member_actions=Vec::new();for v in ordered(entities(d,"en1993_member_action",12,DESIGN,c)?.into_values(),1,c)?{checkpoint(c,member_actions.len(),0)?;member_actions.push(MemberAction{id:text(v,3,c)?,member_id:text(v,4,c)?,load_case_id:text(v,5,c)?,action:DesignAction{n:v.real(6)?,vy:v.real(7)?,vz:v.real(8)?,my:v.real(9)?,mz:v.real(10)?,t:v.real(11)?}});}
  let mut joints=Vec::new();for v in ordered(joint_rows.into_values(),1,c)?{let mut actions=Vec::new();for a in ordered(joint_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?{checkpoint(c,actions.len(),0)?;actions.push(JointForceAction{id:text(a,3,c)?,load_case_id:text(a,4,c)?,shear:a.real(5)?,tension:a.real(6)?});}joints.push(SteelJoint{id:text(v,3,c)?,kind:text(v,4,c)?,member_id:text(v,5,c)?,bolt_class:text(v,6,c)?,bolt_diameter:v.real(7)?,bolt_rows:uint(v,8)?,bolts_per_row:uint(v,9)?,pitch:v.real(10)?,gauge:v.real(11)?,end_distance:v.real(12)?,edge_distance:v.real(13)?,shear_planes:uint(v,14)?,plate_thickness:v.real(15)?,plate_fu:v.real(16)?,weld_throat:v.real(17)?,weld_length:v.real(18)?,weld_fu:v.real(19)?,weld_grade:text(v,20,c)?,actions,category:text(v,21,c)?,friction_mu:v.real(22)?,preload_force:v.real(23)?,slip_factor_ks:v.real(24)?,friction_surfaces:uint(v,25)?});}
  let mut fatigue_details=Vec::new();for v in ordered(fatigue_rows.into_values(),1,c)?{let mut spectrum=Vec::new();for a in ordered(bands.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?{checkpoint(c,spectrum.len(),0)?;spectrum.push(FatigueBand{id:text(a,3,c)?,delta_sigma:a.real(4)?,cycles:a.real(5)?});}fatigue_details.push(FatigueDetail{id:text(v,3,c)?,member_id:text(v,4,c)?,category:category(v,5)?,method:text(v,6,c)?,spectrum});}
  let mut fire_exposures=Vec::new();for v in ordered(entities(d,"en1993_fire_exposure",13,FIRE,c)?.into_values(),1,c)?{checkpoint(c,fire_exposures.len(),0)?;fire_exposures.push(FireExposure{id:text(v,3,c)?,member_id:text(v,4,c)?,rating:text(v,5,c)?,protection_thickness:v.real(6)?,section_factor:v.real(7)?,mu0:v.real(8)?,design_temperature:v.real(9)?,protection_conductivity:v.real(10)?,protection_density:v.real(11)?,protection_specific_heat:v.real(12)?});}
  let mut cold_formed_members=Vec::new();for v in ordered(cold_rows.into_values(),1,c)?{cold_formed_members.push(ColdFormedMember{id:text(v,3,c)?,b_bar:v.real(4)?,thickness:v.real(5)?,k_sigma:v.real(6)?,psi:v.real(7)?,fy:v.real(8)?,gross_resistance:v.real(9)?,actions:read_forces(cold_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?});}
  let mut plated_panels=Vec::new();for v in ordered(plate_rows.into_values(),1,c)?{plated_panels.push(PlatedPanel{id:text(v,3,c)?,a:v.real(4)?,b:v.real(5)?,thickness:v.real(6)?,fy:v.real(7)?,k_sigma:v.real(8)?,actions:read_forces(plate_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?});}
  let mut silo_shells=Vec::new();for v in ordered(entities(d,"en1993_silo_shell",10,SILO,c)?.into_values(),1,c)?{checkpoint(c,silo_shells.len(),0)?;silo_shells.push(SiloShell{id:text(v,3,c)?,thickness:v.real(4)?,radius:v.real(5)?,depth:v.real(6)?,k:v.real(7)?,gamma:v.real(8)?,fy:v.real(9)?});}
  let mut tension_components=Vec::new();for v in ordered(tension_rows.into_values(),1,c)?{tension_components.push(TensionComponent{id:text(v,3,c)?,f_uk:v.real(4)?,f_k:v.real(5)?,actions:read_forces(tension_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?});}
  let mut bridge_fatigue=Vec::new();for v in ordered(entities(d,"en1993_bridge_fatigue",10,BRIDGE,c)?.into_values(),1,c)?{checkpoint(c,bridge_fatigue.len(),0)?;bridge_fatigue.push(BridgeFatigue{id:text(v,3,c)?,member_id:text(v,4,c)?,lambda:v.real(5)?,phi2:v.real(6)?,delta_sigma_p:v.real(7)?,category:category(v,8)?,method:text(v,9,c)?});}
  let mut tower_legs=Vec::new();for v in ordered(tower_rows.into_values(),1,c)?{tower_legs.push(TowerLeg{id:text(v,3,c)?,member_id:text(v,4,c)?,force_coefficient:v.real(5)?,dynamic_factor:v.real(6)?,actions:read_forces(tower_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?});}
  let mut piles=Vec::new();for v in ordered(pile_rows.into_values(),1,c)?{piles.push(SteelPile{id:text(v,3,c)?,section_id:text(v,4,c)?,material_id:text(v,5,c)?,driving_stress:v.real(6)?,embedded_length:v.real(7)?,shaft_perimeter:v.real(8)?,actions:read_forces(pile_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?});}
  let mut crane_runways=Vec::new();for v in ordered(crane_rows.into_values(),1,c)?{crane_runways.push(CraneRunway{id:text(v,3,c)?,member_id:text(v,4,c)?,wheel_contact_length:v.real(5)?,dispersion:v.real(6)?,web_thickness:v.real(7)?,fy:v.real(8)?,phi:v.real(9)?,actions:read_forces(crane_actions.remove(&v.rowid).unwrap_or_default(),v.rowid,c)?});}
  c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(Self{annex,materials,sections,members,load_cases,member_actions,joints,fatigue_details,fire_exposures,cold_formed_members,plated_panels,silo_shells,tension_components,bridge_fatigue,tower_legs,piles,crane_runways})
 }
 fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_artifact_reference::ArtifactDialect,_d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.norm.en1993"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("EN1993 owned dialect differs")));}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1).map_err(store::io_schema::IoError::from_value_error)?;Ok(store::io_schema::IoOutcome::clean(()))}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(), ValueError>{self.admit_sqlite_values(c,SqliteSnapshotPhase::EncodeNative)?;let mut b=NativeEncodingBound::file_only(c)?;let mut rows=1;for n in[self.materials.len(),self.sections.len(),self.members.len(),self.load_cases.len(),self.member_actions.len(),self.joints.len(),self.fatigue_details.len(),self.fire_exposures.len(),self.cold_formed_members.len(),self.plated_panels.len(),self.silo_shells.len(),self.tension_components.len(),self.bridge_fatigue.len(),self.tower_legs.len(),self.piles.len(),self.crane_runways.len()]{admit_rows(&mut b,&mut rows,n)?;}b.add(8192)?;
  for v in &self.materials{admit_strings(&mut b,&[&v.id,&v.grade,&v.subgrade,&v.kind],32768)?;}for v in &self.sections{admit_strings(&mut b,&[&v.id,&v.designation,&v.kind],65536)?;}for v in &self.members{admit_strings(&mut b,&[&v.id,&v.label,&v.member_type,&v.section_id,&v.material_id,&v.load_application,&v.moment_diagram,&v.analysis],32768)?;}for v in &self.load_cases{admit_strings(&mut b,&[&v.id,&v.name,&v.kind,&v.category],8192)?;}for v in &self.member_actions{admit_strings(&mut b,&[&v.id,&v.member_id,&v.load_case_id],32768)?;}for v in &self.joints{admit_strings(&mut b,&[&v.id,&v.kind,&v.member_id,&v.bolt_class,&v.weld_grade,&v.category],65536)?;admit_rows(&mut b,&mut rows,v.actions.len())?;for a in &v.actions{admit_strings(&mut b,&[&a.id,&a.load_case_id],8192)?;}}for v in &self.fatigue_details{admit_strings(&mut b,&[&v.id,&v.member_id,&v.method],8192)?;admit_rows(&mut b,&mut rows,v.spectrum.len())?;for a in &v.spectrum{admit_strings(&mut b,&[&a.id],8192)?;}}for v in &self.fire_exposures{admit_strings(&mut b,&[&v.id,&v.member_id,&v.rating],32768)?;}for v in &self.cold_formed_members{admit_strings(&mut b,&[&v.id],32768)?;admit_forces(&mut b,&mut rows,&v.actions)?;}for v in &self.plated_panels{admit_strings(&mut b,&[&v.id],32768)?;admit_forces(&mut b,&mut rows,&v.actions)?;}for v in &self.silo_shells{admit_strings(&mut b,&[&v.id],32768)?;}for v in &self.tension_components{admit_strings(&mut b,&[&v.id],16384)?;admit_forces(&mut b,&mut rows,&v.actions)?;}for v in &self.bridge_fatigue{admit_strings(&mut b,&[&v.id,&v.member_id,&v.method],16384)?;}for v in &self.tower_legs{admit_strings(&mut b,&[&v.id,&v.member_id],16384)?;admit_forces(&mut b,&mut rows,&v.actions)?;}for v in &self.piles{admit_strings(&mut b,&[&v.id,&v.section_id,&v.material_id],16384)?;admit_forces(&mut b,&mut rows,&v.actions)?;}for v in &self.crane_runways{admit_strings(&mut b,&[&v.id,&v.member_id],32768)?;admit_forces(&mut b,&mut rows,&v.actions)?;}b.finish()
 }
}
fn admit_rows(b:&mut NativeEncodingBound<'_,'_>,rows:&mut usize,add:usize)->Result<(), ValueError>{*rows=rows.checked_add(add).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1993 native row count overflow"))?;b.check_rows(*rows)?;b.checkpoint()}
fn admit_strings(b:&mut NativeEncodingBound<'_,'_>,values:&[&String],bytes:usize)->Result<(), ValueError>{b.add(bytes)?;for s in values{b.repeated(s.len(),24)?;}Ok(())}
fn admit_forces(b:&mut NativeEncodingBound<'_,'_>,rows:&mut usize,values:&[ForceAction])->Result<(), ValueError>{admit_rows(b,rows,values.len())?;for a in values{admit_strings(b,&[&a.id,&a.load_case_id],8192)?;}Ok(())}

